import h5py, json, numpy as np

with h5py.File("/workspace/model.h5mlm", "r") as f:
    print("Groups/keys:", list(f.keys()))
    for key in f.keys():
        print(f"\n--- {key} ---")
        item = f[key]
        if hasattr(item, 'keys'):
            for k in item.keys():
                print(f"  {k}")
                val = item[k]
                if hasattr(val, '__iter__') and not isinstance(val, str):
                    print(f"    type={type(val)}, shape={getattr(val, 'shape', 'N/A')}")
                    try:
                        arr = np.array(val)
                        print(f"    values: {arr}")
                    except:
                        print(f"    {val}")
        else:
            print(f"  value: {np.array(item)}")
PYEOF

